7	import com.example.starter.race.api.ReviseTimeRequest;
8	import com.example.starter.race.api.RevokePenaltyRequest;
9	import com.example.starter.race.api.SealRaceRequest;
10	import com.example.starter.race.api.StandingResponse;
11	import com.example.starter.race.domain.PenaltyType;
12	import com.example.starter.race.domain.RaceStatus;
13	import com.example.starter.race.domain.ResultCalculator;
14	import com.example.starter.race.domain.ResultEntry;
15	import com.example.starter.race.persistence.IdempotencyRow;
16	import com.example.starter.race.persistence.PenaltyRow;
17	import com.example.starter.race.persistence.RaceRow;
18	import com.example.starter.race.persistence.RunnerRow;
19	import com.example.starter.race.persistence.SnapshotEntryRow;
20	import com.example.starter.race.persistence.SnapshotRow;
21	import com.example.starter.race.persistence.RaceRepository;
22	import com.fasterxml.jackson.databind.JsonNode;
23	import com.fasterxml.jackson.databind.ObjectMapper;
24	import org.springframework.dao.DuplicateKeyException;
25	import org.springframework.stereotype.Service;
26	import org.springframework.transaction.annotation.Transactional;
27	
28	import java.nio.charset.StandardCharsets;
29	import java.security.MessageDigest;
30	import java.security.NoSuchAlgorithmException;
31	import java.time.Clock;
32	import java.util.ArrayList;
33	import java.util.HexFormat;
34	import java.util.List;
35	import java.util.Map;
36	import java.util.Optional;
37	import java.util.TreeMap;
38	import java.util.function.Supplier;
