40	/**
41	 * {@link RaceService} 的事务实现。
42	 *
43	 * <p>并发与一致性要点：
44	 * <ul>
45	 *   <li>所有写操作先在 race 行上执行“状态=OPEN 且 version=expectedVersion”的条件 UPDATE，
46	 *       行锁串行化同赛事并发写，版本不匹配/已封榜均为0行并返回409，因此不会遗漏已先提交的变更；</li>
47	 *   <li>封榜在同一事务内完成条件转 SEALED 与全体选手只读快照写入；</li>
48	 *   <li>每个写请求以 requestId 唯一键先插入“进行中”占位行：同键并发阻塞至先行者事务结束；
49	 *       成功后在同一事务内补写原响应；业务失败随事务回滚，不占用 requestId 键；
50	 *       同键同参重放原成功结果，异参返回409。</li>
51	 * </ul>
52	 */
53	@Service
54	public class RaceServiceImpl implements RaceService {
55	
56	    /** 原始完赛耗时上界（毫秒），含端点：1天。 */
57	    private static final long MAX_FINISH_TIME_MS = 86_400_000L;
58	    /** 加时处罚上界（毫秒），含端点：1小时。 */
59	    private static final long MAX_PENALTY_MS = 3_600_000L;
60	    /** 同键并发时等待先行者事务结束的上限（毫秒）。 */
61	    private static final long INFLIGHT_WAIT_MAX_MS = 30_000L;
62	
63	    private final RaceRepository repository;
64	    private final Clock clock;
65	    private final ObjectMapper objectMapper;
66	
67	    public RaceServiceImpl(RaceRepository repository, Clock clock, ObjectMapper objectMapper) {
68	        this.repository = repository;
69	        this.clock = clock;
70	        this.objectMapper = objectMapper;
71	    }
72	
73	    @Override
74	    @Transactional
75	    public ServiceResult createRace(CreateRaceRequest request) {
76	        return withIdempotency(request.requestId(), "CREATE_RACE",
77	                orderedParams("raceId", request.raceId()),
78	                () -> {
79	                    long now = clock.millis();
80	                    try {
81	                        repository.insertRace(request.raceId(), now);
82	                    } catch (DuplicateKeyException ex) {
83	                        throw new ConflictException("赛事已存在: " + request.raceId());
84	                    }
85	                    RaceRow race = repository.findRace(request.raceId()).orElseThrow();
86	                    return ServiceResult.created(new RaceResponse(
87	                            race.raceId(), race.version(), race.status(), race.createdAt()));
88	                });
89	    }
90	
91	    @Override
92	    @Transactional
93	    public ServiceResult registerRunner(String raceId, RegisterRunnerRequest request) {
94	        return withIdempotency(request.requestId(), "REGISTER_RUNNER",
95	                orderedParams(
96	                        "raceId", raceId,
97	                        "bib", request.bib(),
98	                        "expectedVersion", request.expectedVersion(),
99	                        "finishTimeMs", request.finishTimeMs()),
100	                () -> {
101	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
102	                    Long finishTimeMs = request.finishTimeMs();
103	                    validateFinishTime(finishTimeMs, true);
104	                    long now = clock.millis();
105	                    bumpVersion(race, request.expectedVersion());
106	                    try {
107	                        repository.insertRunner(raceId, request.bib(), finishTimeMs, now);
108	                    } catch (DuplicateKeyException ex) {
109	                        throw new ConflictException("参赛号已存在: " + request.bib());
110	                    }
111	                    RunnerRow runner = repository.findRunner(raceId, request.bib()).orElseThrow();
112	                    return ServiceResult.created(ResponseMapper.toRunnerResponse(runner));
113	                });
114	    }
115	
116	    @Override
117	    @Transactional
118	    public ServiceResult reviseTime(String raceId, ReviseTimeRequest request) {
119	        return withIdempotency(request.requestId(), "REVISE_TIME",
120	                orderedParams(
121	                        "raceId", raceId,
122	                        "bib", request.bib(),
123	                        "expectedVersion", request.expectedVersion(),
124	                        "finishTimeMs", request.finishTimeMs()),
125	                () -> {
126	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
127	                    requireRunner(raceId, request.bib());
128	                    validateFinishTime(request.finishTimeMs(), false);
129	                    long now = clock.millis();
130	                    bumpVersion(race, request.expectedVersion());
131	                    int updated = repository.updateRunnerTiming(
132	                            raceId, request.bib(), request.finishTimeMs(), now);
133	                    if (updated == 0) {
134	                        throw new NotFoundException("选手不存在: " + request.bib());
135	                    }
136	                    RunnerRow runner = repository.findRunner(raceId, request.bib()).orElseThrow();
137	                    return ServiceResult.ok(ResponseMapper.toRunnerResponse(runner));
138	                });
139	    }
140	
141	    @Override
142	    @Transactional
143	    public ServiceResult addPenalty(String raceId, AddPenaltyRequest request) {
144	        return withIdempotency(request.requestId(), "ADD_PENALTY",
145	                orderedParams(
146	                        "raceId", raceId,
147	                        "penaltyId", request.penaltyId(),
148	                        "bib", request.bib(),
149	                        "type", request.type(),
150	                        "amountMs", request.amountMs(),
151	                        "expectedVersion", request.expectedVersion()),
152	                () -> {
153	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
154	                    requireRunner(raceId, request.bib());
155	                    PenaltyType type = parsePenaltyType(request.type());
156	                    Long amountMs = request.amountMs();
157	                    if (type == PenaltyType.ADD_TIME) {
158	                        if (amountMs == null) {
159	                            throw new BadRequestException("加时处罚必须携带 amountMs");
160	                        }
161	                        if (amountMs < 1 || amountMs > MAX_PENALTY_MS) {
162	                            throw new BadRequestException("加时毫秒数必须在 1~3600000 之间");
163	                        }
164	                    } else if (amountMs != null) {
165	                        throw new BadRequestException("取消资格处罚不得携带 amountMs");
166	                    }
167	                    long now = clock.millis();
168	                    bumpVersion(race, request.expectedVersion());
169	                    try {
170	                        repository.insertPenalty(
171	                                request.penaltyId(), raceId, request.bib(), type, amountMs, now);
172	                    } catch (DuplicateKeyException ex) {
173	                        throw new ConflictException("处罚ID已存在: " + request.penaltyId());
174	                    }
175	                    PenaltyRow penalty = repository.findPenalty(request.penaltyId()).orElseThrow();
176	                    return ServiceResult.created(ResponseMapper.toPenaltyResponse(penalty));
177	                });
178	    }
179	
180	    @Override
181	    @Transactional
182	    public ServiceResult revokePenalty(
183	            String raceId, String penaltyId, RevokePenaltyRequest request) {
184	        return withIdempotency(request.requestId(), "REVOKE_PENALTY",
185	                orderedParams(
186	                        "raceId", raceId,
187	                        "penaltyId", penaltyId,
188	                        "expectedVersion", request.expectedVersion()),
189	                () -> {
190	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
191	                    PenaltyRow penalty = repository.findPenalty(penaltyId)
192	                            .orElseThrow(() -> new NotFoundException("处罚不存在: " + penaltyId));
193	                    if (!penalty.raceId().equals(raceId)) {
194	                        throw new NotFoundException("处罚不属于该赛事: " + penaltyId);
195	                    }
196	                    if (penalty.revoked()) {
197	                        throw new ConflictException("处罚已撤销: " + penaltyId);
198	                    }
199	                    long now = clock.millis();
200	                    bumpVersion(race, request.expectedVersion());
201	                    int updated = repository.markPenaltyRevoked(penaltyId, now);
202	                    if (updated == 0) {
203	                        throw new ConflictException("处罚已撤销: " + penaltyId);
204	                    }
205	                    PenaltyRow refreshed = repository.findPenalty(penaltyId).orElseThrow();
206	                    return ServiceResult.ok(ResponseMapper.toPenaltyResponse(refreshed));
207	                });
208	    }
209	
210	    @Override
211	    @Transactional
212	    public ServiceResult sealRace(String raceId, SealRaceRequest request) {
213	        return withIdempotency(request.requestId(), "SEAL_RACE",
214	                orderedParams(
215	                        "raceId", raceId,
216	                        "expectedVersion", request.expectedVersion()),
217	                () -> {
218	                    RaceRow race = repository.findRace(raceId)
219	                            .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
220	                    if (race.status() == RaceStatus.SEALED) {
221	                        throw new ConflictException("赛事已封榜: " + raceId);
222	                    }
223	                    List<RunnerRow> runners = repository.findRunners(raceId);
224	                    List<PenaltyRow> penalties = repository.findPenalties(raceId);
225	                    List<ResultEntry> entries = ResultCalculator.compute(runners, penalties);
226	
227	                    int newVersion = request.expectedVersion() + 1;
228	                    int updated = repository.sealIfOpenAtVersion(
229	                            raceId, request.expectedVersion(), newVersion);
230	                    if (updated == 0) {
231	                        throw new ConflictException("版本冲突或赛事已封榜");
232	                    }
233	                    long now = clock.millis();
234	                    List<SnapshotEntryRow> snapshotEntries = new ArrayList<>(entries.size());
235	                    for (int order = 0; order < entries.size(); order++) {
236	                        ResultEntry entry = entries.get(order);
237	                        snapshotEntries.add(new SnapshotEntryRow(
238	                                raceId,
239	                                entry.bib(),
240	                                entry.rank(),
241	                                entry.status(),
242	                                entry.finishTimeMs(),
243	                                entry.penaltyMs(),
244	                                entry.totalTimeMs(),
245	                                order));
246	                    }
247	                    repository.insertSnapshot(new SnapshotRow(raceId, newVersion, now,
248	                            snapshotEntries));
249	                    return ServiceResult.ok(new StandingResponse(
250	                            raceId, newVersion, RaceStatus.SEALED, now,
251	                            snapshotEntries.stream().map(ResponseMapper::toEntryResponse).toList()));
252	                });
253	    }
254	
255	    @Override
256	    @Transactional(readOnly = true)
257	    public StandingResponse getResults(String raceId) {
258	        RaceRow race = repository.findRace(raceId)
259	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
260	        if (race.status() == RaceStatus.SEALED) {
261	            SnapshotRow snapshot = repository.findSnapshot(raceId)
262	                    .orElseThrow(() -> new IllegalStateException(
263	                            "赛事已封榜但缺少快照: " + raceId));
264	            return ResponseMapper.snapshotStanding(snapshot);
265	        }
266	        return ResponseMapper.liveStanding(
267	                race, repository.findRunners(raceId), repository.findPenalties(raceId));
268	    }
269	
270	    @Override
271	    @Transactional(readOnly = true)
272	    public StandingResponse getSnapshot(String raceId) {
273	        repository.findRace(raceId)
274	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
275	        SnapshotRow snapshot = repository.findSnapshot(raceId)
276	                .orElseThrow(() -> new NotFoundException("赛事尚未封榜: " + raceId));
277	        return ResponseMapper.snapshotStanding(snapshot);
278	    }
279	
280	    /**
281	     * 幂等包装：同键同参重放原成功结果，同键异参409；
282	     * 业务异常随事务回滚，占位行消失，不占用 requestId。
283	     */
284	    private ServiceResult withIdempotency(
285	            String requestId,
286	            String operation,
287	            TreeMap<String, Object> params,
288	            Supplier<ServiceResult> action) {
289	        String digest = digest(operation, params);
290	        long deadline = clock.millis() + INFLIGHT_WAIT_MAX_MS;
291	        boolean acquired = false;
292	        while (!acquired) {
293	            try {
294	                repository.insertIdempotencyPlaceholder(
295	                        requestId, operation, digest, clock.millis());
296	                acquired = true;
297	            } catch (DuplicateKeyException ex) {
298	                Optional<IdempotencyRow> existing =
299	                        repository.findIdempotencyForUpdate(requestId);
300	                if (existing.isEmpty()) {
301	                    // 先行者事务回滚，占位行已随其消失，立即重新占位。
302	                    continue;
303	                }
304	                IdempotencyRow row = existing.get();
305	                if (row.responseStatus() == 0) {
306	                    // 理论上不会出现（提交必带最终响应）；防御性等待先行者完成。
307	                    if (clock.millis() >= deadline) {
308	                        throw new ConflictException("相同 requestId 的请求仍在处理中");
309	                    }
310	                    sleepBriefly();
311	                    continue;
312	                }
313	                if (!row.requestDigest().equals(digest)) {
314	                    throw new ConflictException(
315	                            "requestId 已用于不同参数的请求: " + requestId);
316	                }
317	                JsonNode replayedBody = parseReplayedBody(row.responseBody());
318	                return new ServiceResult(replayedBody, row.responseStatus());
319	            }
320	        }
321	        ServiceResult result = action.get();
322	        repository.completeIdempotency(
323	                requestId, result.status(), writeJson(result.body()));
324	        return result;
325	    }
326	
327	    private RaceRow requireOpenRace(String raceId, Integer expectedVersion) {
328	        RaceRow race = repository.findRace(raceId)
329	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
330	        if (race.status() == RaceStatus.SEALED) {
331	            throw new ConflictException("赛事已封榜，禁止写入: " + raceId);
332	        }
333	        if (race.version() != expectedVersion) {
334	            throw new ConflictException("版本冲突: expected=" + expectedVersion
335	                    + ", actual=" + race.version());
336	        }
337	        return race;
338	    }
339	
340	    private void bumpVersion(RaceRow race, int expectedVersion) {
341	        int updated = repository.bumpVersionIfOpen(race.raceId(), expectedVersion);
342	        if (updated == 0) {
343	            // 行锁释放后发现赛事已封榜或版本已被推进。
344	            RaceRow refreshed = repository.findRace(race.raceId()).orElseThrow();
345	            if (refreshed.status() == RaceStatus.SEALED) {
346	                throw new ConflictException("赛事已封榜，禁止写入: " + race.raceId());
347	            }
348	            throw new ConflictException("版本冲突: expected=" + expectedVersion
349	                    + ", actual=" + refreshed.version());
350	        }
351	    }
352	
353	    private RunnerRow requireRunner(String raceId, String bib) {
354	        return repository.findRunner(raceId, bib)
355	                .orElseThrow(() -> new NotFoundException("选手不存在: " + bib));
356	    }
357	
358	    private static void validateFinishTime(Long finishTimeMs, boolean nullable) {
359	        if (finishTimeMs == null) {
360	            if (!nullable) {
361	                throw new BadRequestException("修订计时必须携带 finishTimeMs");
362	            }
363	            return;
364	        }
365	        if (finishTimeMs < 1 || finishTimeMs > MAX_FINISH_TIME_MS) {
366	            throw new BadRequestException("完赛耗时毫秒数必须在 1~86400000 之间");
367	        }
368	    }
369	
370	    private static PenaltyType parsePenaltyType(String type) {
371	        try {
372	            return PenaltyType.valueOf(type);
373	        } catch (IllegalArgumentException ex) {
374	            throw new BadRequestException("未知处罚类型: " + type);
375	        }
376	    }
377	
378	    private static TreeMap<String, Object> orderedParams(Object... keyValues) {
379	        if (keyValues.length % 2 != 0) {
380	            throw new IllegalArgumentException("参数必须为键值对");
381	        }
382	        TreeMap<String, Object> params = new TreeMap<>();
383	        for (int i = 0; i < keyValues.length; i += 2) {
384	            params.put((String) keyValues[i], keyValues[i + 1]);
385	        }
386	        return params;
387	    }
388	
389	    private String digest(String operation, Map<String, Object> params) {
390	        try {
391	            Map<String, Object> canonical = new TreeMap<>(params);
392	            canonical.put("__operation", operation);
393	            MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");
394	            byte[] bytes = objectMapper.writerWithDefaultPrettyPrinter()
395	                    .writeValueAsString(canonical)
396	                    .getBytes(StandardCharsets.UTF_8);
397	            return HexFormat.of().formatHex(messageDigest.digest(bytes));
398	        } catch (NoSuchAlgorithmException | com.fasterxml.jackson.core.JsonProcessingException ex) {
399	            throw new IllegalStateException("计算请求摘要失败", ex);
400	        }
401	    }
402	
403	    private String writeJson(Object body) {
404	        try {
405	            return objectMapper.writeValueAsString(body);
406	        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
407	            throw new IllegalStateException("序列化响应失败", ex);
408	        }
409	    }
410	
411	    private JsonNode parseReplayedBody(String body) {
412	        try {
413	            return objectMapper.readTree(body);
414	        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
415	            throw new IllegalStateException("解析原响应失败", ex);
416	        }
417	    }
418	
419	    private static void sleepBriefly() {
420	        try {
421	            Thread.sleep(10L);
422	        } catch (InterruptedException ex) {
423	            Thread.currentThread().interrupt();
424	            throw new ConflictException("等待同键请求完成时被中断");
425	        }
426	    }
427	}
