package com.example.starter.race.service;

/**
 * 写操作的服务返回：响应体与首次成功时的 HTTP 状态码；
 * 幂等重放时由控制器原样返回。
 *
 * @param body   响应体（Jackson 可序列化对象；重放时为解析后的 JsonNode）
 * @param status 首次成功的 HTTP 状态码
 */
public record ServiceResult(Object body, int status) {

    public static ServiceResult ok(Object body) {
        return new ServiceResult(body, 200);
    }

    public static ServiceResult created(Object body) {
        return new ServiceResult(body, 201);
    }
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 新建赛事请求。
 *
 * @param raceId    赛事ID，全局唯一
 * @param requestId 全局唯一请求ID（幂等键）
 */
public record CreateRaceRequest(
        @NotBlank String raceId,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 封榜请求；校验版本后原子保存全体选手只读成绩快照并转 SEALED。
 *
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record SealRaceRequest(
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.domain;

/**
 * 选手成绩状态：RANKED-正常参与排名；UNTIMED-计时缺失不排名；DISQUALIFIED-存在生效取消资格处罚不排名。
 */
public enum EntryStatus {
    RANKED,
    UNTIMED,
    DISQUALIFIED
}

package com.example.starter.race.domain;

/**
 * 单个选手的成绩条目。
 *
 * @param bib           参赛号
 * @param rank          名次，从1开始；并列同名次且跳号（1、1、3）；UNTIMED/DISQUALIFIED 为 null
 * @param status        成绩状态
 * @param finishTimeMs  原始完赛耗时（毫秒）；计时缺失为 null
 * @param penaltyMs     全部未撤销加时处罚的合计毫秒数；无加时为 0
 * @param totalTimeMs   总耗时=原始完赛耗时+生效加时（毫秒）；未排名时为 null
 */
public record ResultEntry(
        String bib,
        Integer rank,
        EntryStatus status,
        Long finishTimeMs,
        long penaltyMs,
        Long totalTimeMs
) {
}

